# WITHOUT caching -- every single redirect hits the database
def redirect_naive(short_code):
    row = database.query("SELECT long_url FROM urls WHERE short_code = %s", short_code)
    if row is None:
        return not_found_response()
    return redirect_response(row.long_url, status=302)

# WITH cache-aside and a long TTL -- matches the near-immutability of the mapping
CACHE_TTL_SECONDS = 86400  # 24 hours -- mappings essentially never change once created

def redirect_cached(short_code):
    cache_key = f"url:{short_code}"
    long_url = cache.get(cache_key)
    if long_url is not None:
        return redirect_response(long_url, status=302)   # cache hit -- DB never touched

    row = database.query("SELECT long_url FROM urls WHERE short_code = %s", short_code)
    if row is None:
        return not_found_response()
    cache.set(cache_key, row.long_url, ex=CACHE_TTL_SECONDS)
    return redirect_response(row.long_url, status=302)

