import queue_client  # any async task/queue mechanism (message queue, background worker, etc.)

def redirect_handler(short_code, request_metadata):
    long_url = cache.get(f"url:{short_code}") or lookup_and_cache(short_code)
    if long_url is None:
        return not_found_response()

    # fire-and-forget: enqueue the analytics event, don't wait for it,
    # and don't let its failure affect the redirect response at all
    queue_client.enqueue("click_events", {
        "short_code": short_code,
        "timestamp": now(),
        "referrer": request_metadata.referrer,
        "user_agent": request_metadata.user_agent,
    })

    return redirect_response(long_url, status=302)  # responds immediately,
                                                       # independent of analytics write

