def send_message(conversation_id, sender_id, recipient_id, client_message_id, text):
    # STEP 1: persist FIRST, unconditionally -- this is the actual guarantee
    sequence_number = message_store.append(
        conversation_id, sender_id, client_message_id, text
    )   # durable write; if this succeeds, the message is never lost,
        # regardless of what happens next

    # STEP 2: attempt live delivery, best-effort, AFTER durability is secured
    recipient_server = connection_registry.get(f"conn:{recipient_id}")
    if recipient_server is not None:
        try:
            deliver_live(recipient_server, conversation_id, sequence_number, text)
        except DeliveryError:
            pass  # fine -- recipient will catch up via reconnect sync, see below

    return sequence_number

# on the recipient's client reconnecting after being offline:
def sync_on_reconnect(conversation_id, last_seen_sequence_number):
    return message_store.get_since(conversation_id, last_seen_sequence_number)

